-- 01 | easy | Reverse Linked List
SELECT pg_temp.seed_coding($q$Linked Lists$q$, 'easy', $q$Reverse Linked List$q$, $q$Reverse a singly linked list and print the reversed list. The list is given as its node values; your function receives the head node and must return the head of the resulting list.

Input Format:
- head: an integer n, then n space-separated integers (the node values of a singly linked list; n may be 0)

Output Format:
Print the node values of the resulting linked list on one line, separated by single spaces.

Example:
Input:
5
1 2 3 4 5
Output:
5 4 3 2 1$q$,
  $q$def reverse_list(head: Optional[ListNode]) -> Optional[ListNode]$q$, $j${"python":"import sys\nfrom typing import List, Optional\n\nclass ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef reverse_list(head: Optional[ListNode]) -> Optional[ListNode]:\n    # Write your solution here\n    pass\n\n\ndef build_list(vals):\n    head = None\n    for v in reversed(vals):\n        head = ListNode(v, head)\n    return head\n\n\ndef main():\n    it = iter(sys.stdin.read().split())\n    head = build_list([int(next(it)) for _ in range(int(next(it)))])\n    result = reverse_list(head)\n    vals = []\n    while result:\n        vals.append(str(result.val))\n        result = result.next\n    print(' '.join(vals))\n\n\nmain()\n","javascript":"const tokens = require('fs').readFileSync(0, 'utf8').split(/\\s+/).filter(Boolean);\nlet pos = 0;\nconst next = () => tokens[pos++];\n\nclass ListNode {\n  constructor(val = 0, next = null) {\n    this.val = val;\n    this.next = next;\n  }\n}\n\nfunction reverseList(head) {\n  // Write your solution here\n}\n\nfunction buildList(vals) {\n  let head = null;\n  for (let i = vals.length - 1; i >= 0; i--) {\n    head = new ListNode(vals[i], head);\n  }\n  return head;\n}\n\nconst head = buildList(Array.from({ length: parseInt(next()) }, () => parseInt(next())));\nconst result = reverseList(head);\nconst vals = [];\nfor (let cur = result; cur !== null; cur = cur.next) vals.push(cur.val);\nconsole.log(vals.join(' '));\n","java":"import java.util.*;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n    }\n\n    static ListNode reverseList(ListNode head) {\n        // Write your solution here\n        return null;\n    }\n\n    static ListNode buildList(int[] vals) {\n        ListNode head = null;\n        for (int i = vals.length - 1; i >= 0; i--) {\n            ListNode node = new ListNode(vals[i]);\n            node.next = head;\n            head = node;\n        }\n        return head;\n    }\n\n    public static void main(String[] mainArgs) {\n        Scanner scanner = new Scanner(System.in);\n        int[] headVals = new int[scanner.nextInt()];\n        for (int i = 0; i < headVals.length; i++) headVals[i] = scanner.nextInt();\n        ListNode head = buildList(headVals);\n        ListNode result = reverseList(head);\n        StringBuilder sb = new StringBuilder();\n        for (ListNode cur = result; cur != null; cur = cur.next) {\n            if (sb.length() > 0) sb.append(' ');\n            sb.append(cur.val);\n        }\n        System.out.println(sb);\n    }\n}\n","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nListNode* reverseList(ListNode* head) {\n    // Write your solution here\n    return nullptr;\n}\n\nListNode* buildList(const vector<int>& vals) {\n    ListNode* head = nullptr;\n    for (int i = (int)vals.size() - 1; i >= 0; i--) {\n        ListNode* node = new ListNode(vals[i]);\n        node->next = head;\n        head = node;\n    }\n    return head;\n}\n\nint main() {\n    int headN;\n    cin >> headN;\n    vector<int> headVals(headN);\n    for (int& x : headVals) cin >> x;\n    ListNode* head = buildList(headVals);\n    auto result = reverseList(head);\n    for (ListNode* cur = result; cur; cur = cur->next) {\n        if (cur != result) cout << ' ';\n        cout << cur->val;\n    }\n    cout << endl;\n    return 0;\n}\n"}$j$::jsonb, $j$[{"input":"5\n1 2 3 4 5","expected":"5 4 3 2 1"},{"input":"2\n1 2","expected":"2 1"},{"input":"1\n7","expected":"7"},{"input":"9\n1 6 2 2 5 8 2 3 4","expected":"4 3 2 8 5 2 2 6 1"},{"input":"7\n2 1 6 6 2 2 4","expected":"4 2 2 6 6 1 2"},{"input":"5\n7 4 3 6 7","expected":"7 6 3 4 7"}]$j$::jsonb,
  $q$1 <= n <= 5000$q$, 2000, 131072, ARRAY[71,63,62,54],
  ARRAY['Amazon','TCS','Infosys','Wipro','Accenture']::text[], ARRAY['linked-list','iteration']::text[]);

