-- 03 | easy | Merge Two Sorted Lists
SELECT pg_temp.seed_coding($q$Linked Lists$q$, 'easy', $q$Merge Two Sorted Lists$q$, $q$Merge two sorted linked lists into one sorted list by splicing their nodes together. The list is given as its node values; your function receives the head node and must return the head of the resulting list.

Input Format:
- list1: an integer n, then n space-separated integers (the node values of a singly linked list; n may be 0)
- list2: an integer n, then n space-separated integers (the node values of a singly linked list; n may be 0)

Output Format:
Print the node values of the resulting linked list on one line, separated by single spaces.

Example:
Input:
3
1 2 4
3
1 3 4
Output:
1 1 2 3 4 4$q$,
  $q$def merge_two_lists(list1: Optional[ListNode], list2: Optional[ListNode]) -> Optional[ListNode]$q$, $j${"python":"import sys\nfrom typing import List, Optional\n\nclass ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef merge_two_lists(list1: Optional[ListNode], list2: Optional[ListNode]) -> Optional[ListNode]:\n    # Write your solution here\n    pass\n\n\ndef build_list(vals):\n    head = None\n    for v in reversed(vals):\n        head = ListNode(v, head)\n    return head\n\n\ndef main():\n    it = iter(sys.stdin.read().split())\n    list1 = build_list([int(next(it)) for _ in range(int(next(it)))])\n    list2 = build_list([int(next(it)) for _ in range(int(next(it)))])\n    result = merge_two_lists(list1, list2)\n    vals = []\n    while result:\n        vals.append(str(result.val))\n        result = result.next\n    print(' '.join(vals))\n\n\nmain()\n","javascript":"const tokens = require('fs').readFileSync(0, 'utf8').split(/\\s+/).filter(Boolean);\nlet pos = 0;\nconst next = () => tokens[pos++];\n\nclass ListNode {\n  constructor(val = 0, next = null) {\n    this.val = val;\n    this.next = next;\n  }\n}\n\nfunction mergeTwoLists(list1, list2) {\n  // Write your solution here\n}\n\nfunction buildList(vals) {\n  let head = null;\n  for (let i = vals.length - 1; i >= 0; i--) {\n    head = new ListNode(vals[i], head);\n  }\n  return head;\n}\n\nconst list1 = buildList(Array.from({ length: parseInt(next()) }, () => parseInt(next())));\nconst list2 = buildList(Array.from({ length: parseInt(next()) }, () => parseInt(next())));\nconst result = mergeTwoLists(list1, list2);\nconst vals = [];\nfor (let cur = result; cur !== null; cur = cur.next) vals.push(cur.val);\nconsole.log(vals.join(' '));\n","java":"import java.util.*;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n    }\n\n    static ListNode mergeTwoLists(ListNode list1, ListNode list2) {\n        // Write your solution here\n        return null;\n    }\n\n    static ListNode buildList(int[] vals) {\n        ListNode head = null;\n        for (int i = vals.length - 1; i >= 0; i--) {\n            ListNode node = new ListNode(vals[i]);\n            node.next = head;\n            head = node;\n        }\n        return head;\n    }\n\n    public static void main(String[] mainArgs) {\n        Scanner scanner = new Scanner(System.in);\n        int[] list1Vals = new int[scanner.nextInt()];\n        for (int i = 0; i < list1Vals.length; i++) list1Vals[i] = scanner.nextInt();\n        ListNode list1 = buildList(list1Vals);\n        int[] list2Vals = new int[scanner.nextInt()];\n        for (int i = 0; i < list2Vals.length; i++) list2Vals[i] = scanner.nextInt();\n        ListNode list2 = buildList(list2Vals);\n        ListNode result = mergeTwoLists(list1, list2);\n        StringBuilder sb = new StringBuilder();\n        for (ListNode cur = result; cur != null; cur = cur.next) {\n            if (sb.length() > 0) sb.append(' ');\n            sb.append(cur.val);\n        }\n        System.out.println(sb);\n    }\n}\n","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nListNode* mergeTwoLists(ListNode* list1, ListNode* list2) {\n    // Write your solution here\n    return nullptr;\n}\n\nListNode* buildList(const vector<int>& vals) {\n    ListNode* head = nullptr;\n    for (int i = (int)vals.size() - 1; i >= 0; i--) {\n        ListNode* node = new ListNode(vals[i]);\n        node->next = head;\n        head = node;\n    }\n    return head;\n}\n\nint main() {\n    int list1N;\n    cin >> list1N;\n    vector<int> list1Vals(list1N);\n    for (int& x : list1Vals) cin >> x;\n    ListNode* list1 = buildList(list1Vals);\n    int list2N;\n    cin >> list2N;\n    vector<int> list2Vals(list2N);\n    for (int& x : list2Vals) cin >> x;\n    ListNode* list2 = buildList(list2Vals);\n    auto result = mergeTwoLists(list1, list2);\n    for (ListNode* cur = result; cur; cur = cur->next) {\n        if (cur != result) cout << ' ';\n        cout << cur->val;\n    }\n    cout << endl;\n    return 0;\n}\n"}$j$::jsonb, $j$[{"input":"3\n1 2 4\n3\n1 3 4","expected":"1 1 2 3 4 4"},{"input":"0\n\n1\n0","expected":"0"},{"input":"2\n5 6\n0\n","expected":"5 6"},{"input":"3\n7 9 9\n7\n0 4 7 9 10 12 15","expected":"0 4 7 7 9 9 9 10 12 15"},{"input":"7\n0 1 6 13 13 14 15\n7\n0 5 7 9 10 11 14","expected":"0 0 1 5 6 7 9 10 11 13 13 14 14 15"},{"input":"4\n4 11 11 11\n6\n5 6 8 10 11 12","expected":"4 5 6 8 10 11 11 11 11 12"}]$j$::jsonb,
