-- 05 | easy | Palindrome Linked List
SELECT pg_temp.seed_coding($q$Linked Lists$q$, 'easy', $q$Palindrome Linked List$q$, $q$Print true if the list reads the same forwards and backwards. Try for O(n) time and O(1) extra space.

Input Format:
- head: an integer n, then n space-separated integers (the node values of a singly linked list; n may be 0)

Output Format:
Print true or false (lowercase).

Example:
Input:
4
1 2 2 1
Output:
true$q$,
  $q$def is_palindrome(head: Optional[ListNode]) -> bool$q$, $j${"python":"import sys\nfrom typing import List, Optional\n\nclass ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef is_palindrome(head: Optional[ListNode]) -> bool:\n    # Write your solution here\n    pass\n\n\ndef build_list(vals):\n    head = None\n    for v in reversed(vals):\n        head = ListNode(v, head)\n    return head\n\n\ndef main():\n    it = iter(sys.stdin.read().split())\n    head = build_list([int(next(it)) for _ in range(int(next(it)))])\n    result = is_palindrome(head)\n    print('true' if result else 'false')\n\n\nmain()\n","javascript":"const tokens = require('fs').readFileSync(0, 'utf8').split(/\\s+/).filter(Boolean);\nlet pos = 0;\nconst next = () => tokens[pos++];\n\nclass ListNode {\n  constructor(val = 0, next = null) {\n    this.val = val;\n    this.next = next;\n  }\n}\n\nfunction isPalindrome(head) {\n  // Write your solution here\n}\n\nfunction buildList(vals) {\n  let head = null;\n  for (let i = vals.length - 1; i >= 0; i--) {\n    head = new ListNode(vals[i], head);\n  }\n  return head;\n}\n\nconst head = buildList(Array.from({ length: parseInt(next()) }, () => parseInt(next())));\nconst result = isPalindrome(head);\nconsole.log(result ? 'true' : 'false');\n","java":"import java.util.*;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n    }\n\n    static boolean isPalindrome(ListNode head) {\n        // Write your solution here\n        return false;\n    }\n\n    static ListNode buildList(int[] vals) {\n        ListNode head = null;\n        for (int i = vals.length - 1; i >= 0; i--) {\n            ListNode node = new ListNode(vals[i]);\n            node.next = head;\n            head = node;\n        }\n        return head;\n    }\n\n    public static void main(String[] mainArgs) {\n        Scanner scanner = new Scanner(System.in);\n        int[] headVals = new int[scanner.nextInt()];\n        for (int i = 0; i < headVals.length; i++) headVals[i] = scanner.nextInt();\n        ListNode head = buildList(headVals);\n        boolean result = isPalindrome(head);\n        System.out.println(result ? \"true\" : \"false\");\n    }\n}\n","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nbool isPalindrome(ListNode* head) {\n    // Write your solution here\n    return false;\n}\n\nListNode* buildList(const vector<int>& vals) {\n    ListNode* head = nullptr;\n    for (int i = (int)vals.size() - 1; i >= 0; i--) {\n        ListNode* node = new ListNode(vals[i]);\n        node->next = head;\n        head = node;\n    }\n    return head;\n}\n\nint main() {\n    int headN;\n    cin >> headN;\n    vector<int> headVals(headN);\n    for (int& x : headVals) cin >> x;\n    ListNode* head = buildList(headVals);\n    auto result = isPalindrome(head);\n    cout << (result ? \"true\" : \"false\") << endl;\n    return 0;\n}\n"}$j$::jsonb, $j$[{"input":"4\n1 2 2 1","expected":"true"},{"input":"2\n1 2","expected":"false"},{"input":"1\n5","expected":"true"},{"input":"8\n4 2 3 2 2 3 2 4","expected":"true"},{"input":"7\n1 1 1 3 2 1 1","expected":"false"},{"input":"6\n2 1 3 2 3 1","expected":"false"}]$j$::jsonb,
