-- 20 | medium | Double a Number Represented as a Linked List
SELECT pg_temp.seed_coding($q$Linked Lists$q$, 'medium', $q$Double a Number Represented as a Linked List$q$, $q$The list holds the digits of a non-negative integer, most significant digit first (no leading zeros except for the value 0). Print the digits of the number doubled. The list is given as its node values; your function receives the head node and must return the head of the resulting list.

Input Format:
- head: an integer n, then n space-separated integers (the node values of a singly linked list; n may be 0)

Output Format:
Print the node values of the resulting linked list on one line, separated by single spaces.

Example:
Input:
3
1 8 9
Output:
3 7 8$q$,
  $q$def double_it(head: Optional[ListNode]) -> Optional[ListNode]$q$, $j${"python":"import sys\nfrom typing import List, Optional\n\nclass ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef double_it(head: Optional[ListNode]) -> Optional[ListNode]:\n    # Write your solution here\n    pass\n\n\ndef build_list(vals):\n    head = None\n    for v in reversed(vals):\n        head = ListNode(v, head)\n    return head\n\n\ndef main():\n    it = iter(sys.stdin.read().split())\n    head = build_list([int(next(it)) for _ in range(int(next(it)))])\n    result = double_it(head)\n    vals = []\n    while result:\n        vals.append(str(result.val))\n        result = result.next\n    print(' '.join(vals))\n\n\nmain()\n","javascript":"const tokens = require('fs').readFileSync(0, 'utf8').split(/\\s+/).filter(Boolean);\nlet pos = 0;\nconst next = () => tokens[pos++];\n\nclass ListNode {\n  constructor(val = 0, next = null) {\n    this.val = val;\n    this.next = next;\n  }\n}\n\nfunction doubleIt(head) {\n  // Write your solution here\n}\n\nfunction buildList(vals) {\n  let head = null;\n  for (let i = vals.length - 1; i >= 0; i--) {\n    head = new ListNode(vals[i], head);\n  }\n  return head;\n}\n\nconst head = buildList(Array.from({ length: parseInt(next()) }, () => parseInt(next())));\nconst result = doubleIt(head);\nconst vals = [];\nfor (let cur = result; cur !== null; cur = cur.next) vals.push(cur.val);\nconsole.log(vals.join(' '));\n","java":"import java.util.*;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n    }\n\n    static ListNode doubleIt(ListNode head) {\n        // Write your solution here\n        return null;\n    }\n\n    static ListNode buildList(int[] vals) {\n        ListNode head = null;\n        for (int i = vals.length - 1; i >= 0; i--) {\n            ListNode node = new ListNode(vals[i]);\n            node.next = head;\n            head = node;\n        }\n        return head;\n    }\n\n    public static void main(String[] mainArgs) {\n        Scanner scanner = new Scanner(System.in);\n        int[] headVals = new int[scanner.nextInt()];\n        for (int i = 0; i < headVals.length; i++) headVals[i] = scanner.nextInt();\n        ListNode head = buildList(headVals);\n        ListNode result = doubleIt(head);\n        StringBuilder sb = new StringBuilder();\n        for (ListNode cur = result; cur != null; cur = cur.next) {\n            if (sb.length() > 0) sb.append(' ');\n            sb.append(cur.val);\n        }\n        System.out.println(sb);\n    }\n}\n","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nListNode* doubleIt(ListNode* head) {\n    // Write your solution here\n    return nullptr;\n}\n\nListNode* buildList(const vector<int>& vals) {\n    ListNode* head = nullptr;\n    for (int i = (int)vals.size() - 1; i >= 0; i--) {\n        ListNode* node = new ListNode(vals[i]);\n        node->next = head;\n        head = node;\n    }\n    return head;\n}\n\nint main() {\n    int headN;\n    cin >> headN;\n    vector<int> headVals(headN);\n    for (int& x : headVals) cin >> x;\n    ListNode* head = buildList(headVals);\n    auto result = doubleIt(head);\n    for (ListNode* cur = result; cur; cur = cur->next) {\n        if (cur != result) cout << ' ';\n        cout << cur->val;\n    }\n    cout << endl;\n    return 0;\n}\n"}$j$::jsonb, $j$[{"input":"3\n1 8 9","expected":"3 7 8"},{"input":"3\n9 9 9","expected":"1 9 9 8"},{"input":"1\n0","expected":"0"},{"input":"4\n1 8 7 6","expected":"3 7 5 2"},{"input":"5\n4 4 5 1 9","expected":"8 9 0 3 8"},{"input":"6\n3 0 1 5 4 4","expected":"6 0 3 0 8 8"}]$j$::jsonb,
