       for (int i = vals.length - 1; i >= 0; i--) {\n            ListNode node = new ListNode(vals[i]);\n            node.next = head;\n            head = node;\n        }\n        return head;\n    }\n\n    public static void main(String[] mainArgs) {\n        Scanner scanner = new Scanner(System.in);\n        int[] headVals = new int[scanner.nextInt()];\n        for (int i = 0; i < headVals.length; i++) headVals[i] = scanner.nextInt();\n        ListNode head = buildList(headVals);\n        int k = scanner.nextInt();\n        ListNode result = reverseKGroup(head, k);\n        StringBuilder sb = new StringBuilder();\n        for (ListNode cur = result; cur != null; cur = cur.next) {\n            if (sb.length() > 0) sb.append(' ');\n            sb.append(cur.val);\n        }\n        System.out.println(sb);\n    }\n}\n","cpp":"#include <bits/stdc++.h>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nListNode* reverseKGroup(ListNode* head, int k) {\n    // Write your solution here\n    return nullptr;\n}\n\nListNode* buildList(const vector<int>& vals) {\n    ListNode* head = nullptr;\n    for (int i = (int)vals.size() - 1; i >= 0; i--) {\n        ListNode* node = new ListNode(vals[i]);\n        node->next = head;\n        head = node;\n    }\n    return head;\n}\n\nint main() {\n    int headN;\n    cin >> headN;\n    vector<int> headVals(headN);\n    for (int& x : headVals) cin >> x;\n    ListNode* head = buildList(headVals);\n    int k;\n    cin >> k;\n    auto result = reverseKGroup(head, k);\n    for (ListNode* cur = result; cur; cur = cur->next) {\n        if (cur != result) cout << ' ';\n        cout << cur->val;\n    }\n    cout << endl;\n    return 0;\n}\n"}$j$::jsonb, $j$[{"input":"5\n1 2 3 4 5\n2","expected":"2 1 4 3 5"},{"input":"5\n1 2 3 4 5\n3","expected":"3 2 1 4 5"},{"input":"2\n1 2\n1","expected":"1 2"},{"input":"8\n8 9 7 4 4 6 7 9\n4","expected":"4 7 9 8 9 7 6 4"},{"in